#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
PUBLIC_IP="90.189.208.25"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
CSTRIKE="/srv/hyper-cs16/servers/$SID/cstrike"
FASTDL="/srv/hyper-cs16/fastdl/$SID"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-fastdl-final-v6-${STAMP}"
CANON="/etc/nginx/sites-available/00-hyper-cs16-fastdl-ip.conf"
LINK="/etc/nginx/sites-enabled/00-hyper-cs16-fastdl-ip.conf"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing $SRC_CTL"; exit 2; }
[[ -d "$CSTRIKE" ]] || { echo "[ERROR] missing $CSTRIKE"; exit 2; }

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$CSTRIKE/server.cfg" ]] && cp -a "$CSTRIKE/server.cfg" "$BACKUP/server.cfg"
nginx -T >"$BACKUP/nginx-T-before.txt" 2>&1 || true

echo "=============================================================="
echo " HYPER-HOST FASTDL FINAL v6"
echo " Server: #$SID"
echo " URL:    http://$PUBLIC_IP/fastdl/$SID/"
echo "=============================================================="

echo "[1/9] Disable old FastDL 8080 nginx experiments..."
for d in /etc/nginx/conf.d /etc/nginx/sites-enabled; do
  [[ -d "$d" ]] || continue
  while IFS= read -r -d '' f; do
    [[ "$(readlink -f "$f")" == "$(readlink -f "$CANON" 2>/dev/null || true)" ]] && continue
    if grep -qi 'fastdl' "$f" 2>/dev/null && grep -Eq 'listen[[:space:]]+.*8080' "$f" 2>/dev/null; then
      echo "disable: $f"
      cp -aL "$f" "$BACKUP/$(basename "$f").8080.conf" 2>/dev/null || true
      rm -f "$f"
    fi
  done < <(find "$d" -maxdepth 1 \( -type f -o -type l \) -print0 2>/dev/null)
done

echo "[2/9] Install exact-IP FastDL vhost on HTTP/80..."
mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled
cat >"$CANON" <<'EOF'
server {
    listen 80;
    listen [::]:80;
    server_name 90.189.208.25;

    access_log /var/log/nginx/hyper-cs16-fastdl-access.log;
    error_log  /var/log/nginx/hyper-cs16-fastdl-error.log warn;

    location ^~ /fastdl/ {
        alias /srv/hyper-cs16/fastdl/;
        autoindex off;
        default_type application/octet-stream;
        add_header Cache-Control "public, max-age=86400" always;
        add_header X-Hyper-FastDL "raw" always;
    }

    location / {
        return 404;
    }
}
EOF
ln -sfn "$CANON" "$LINK"
nginx -t
systemctl reload nginx

echo "[3/9] Patch all core FastDL functions..."
P="$(mktemp)"
echo '' | base64 -d >"$P"
python3 "$P" "$SRC_CTL"
python3 -m py_compile "$SRC_CTL"
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
rm -f "$P"

echo "[4/9] Validate source BSP..."
python3 - "$CSTRIKE/maps" <<'PY'
from pathlib import Path
import struct,sys
bad=[]; good=0
for p in sorted(Path(sys.argv[1]).glob('*.bsp')):
    with p.open('rb') as f: h=f.read(4)
    v=struct.unpack('<I',h)[0] if len(h)==4 else None
    if v==30: good+=1
    else: bad.append((p.name,v,h.hex()))
print("valid BSP:",good)
print("bad BSP:",len(bad))
for x in bad: print("BAD",x)
if bad: raise SystemExit(3)
PY

echo "[5/9] Full clean sync..."
"$LIVE_CTL" fastdl-sync "$SID"

echo "[6/9] Restart HLDS..."
systemctl restart "hyper-cs16@${SID}.service"
sleep 3

echo "[7/9] Verify every BSP through nginx..."
python3 - "$FASTDL/maps" "$SID" <<'PY'
from pathlib import Path
import urllib.request,urllib.parse,struct,sys
root=Path(sys.argv[1]); sid=int(sys.argv[2])
bad=[]; checked=0
for p in sorted(root.glob('*.bsp')):
    rel='maps/'+p.name
    url='http://127.0.0.1/fastdl/%d/%s'%(sid,urllib.parse.quote(rel,safe='/._-+()[]'))
    req=urllib.request.Request(url,headers={'Host':'90.189.208.25','User-Agent':'GoldSrc-FastDL-Test'})
    try:
        with urllib.request.urlopen(req,timeout=8) as r:
            data=r.read(); code=r.status
    except Exception as e:
        bad.append((p.name,'request',str(e))); continue
    checked+=1
    head=data[:4]
    ver=struct.unpack('<I',head)[0] if len(head)==4 else None
    if code!=200 or ver!=30 or len(data)!=p.stat().st_size:
        bad.append((p.name,code,ver,head.hex(),len(data),p.stat().st_size))
print("HTTP BSP checked:",checked)
print("HTTP BSP bad:",len(bad))
for x in bad[:50]: print("BAD",x)
if bad: raise SystemExit(4)
PY

echo "[8/9] Check repaired server.cfg..."
python3 - "$CSTRIKE/server.cfg" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1]); raw=p.read_bytes(); txt=raw.decode('utf-8','ignore')
print("real LF:",raw.count(b'\n'))
print("literal \\n:",raw.count(b'\\n'))
print("FastDL blocks:",len(re.findall(r'(?im)^\s*// HYPER-HOST FASTDL BEGIN\s*$',txt)))
print("sv_downloadurl entries:",len(re.findall(r'(?im)^\s*sv_downloadurl\b',txt)))
PY

echo "[9/9] Runtime/status..."
"$LIVE_CTL" fastdl-status "$SID" || true
"$LIVE_CTL" rcon "$SID" "sv_downloadurl" || true
"$LIVE_CTL" rcon "$SID" "sv_allowdownload" || true

echo
echo "[SUCCESS] FASTDL FINAL v6"
echo "URL: http://$PUBLIC_IP/fastdl/$SID/"
echo "8080 is no longer used."
echo "Backup: $BACKUP"
